"use strict";
import { useQuery } from "@tanstack/react-query";
import { usePublicClient } from "wagmi";
import { formatUnits } from "viem";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { MORPHO_VAULTS, MORPHO_VAULT_ABI, ERC20_ABI } from "constants/morpho";
export function useMorphoUserVaultPosition(vaultAddress, userAddress, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-user-vault-position", vaultAddress, userAddress, chainId],
    queryFn: async () => {
      if (!publicClient || !vaultAddress || !userAddress) return null;
      const vaultConfig = Object.values(MORPHO_VAULTS).find(
        (v) => v.address.toLowerCase() === vaultAddress.toLowerCase() && v.chainId === chainId
      );
      if (!vaultConfig) {
        console.error(`Vault config not found for address ${vaultAddress}`);
        return null;
      }
      try {
        const [shares, maxWithdraw, maxRedeem, walletBalance] = await publicClient.multicall({
          allowFailure: false,
          contracts: [
            {
              address: vaultAddress,
              abi: MORPHO_VAULT_ABI,
              functionName: "balanceOf",
              args: [userAddress]
            },
            {
              address: vaultAddress,
              abi: MORPHO_VAULT_ABI,
              functionName: "maxWithdraw",
              args: [userAddress]
            },
            {
              address: vaultAddress,
              abi: MORPHO_VAULT_ABI,
              functionName: "maxRedeem",
              args: [userAddress]
            },
            {
              address: vaultConfig.asset.address,
              abi: ERC20_ABI,
              functionName: "balanceOf",
              args: [userAddress]
            }
          ]
        });
        let assetsValue = 0n;
        if (shares > 0n) {
          assetsValue = await publicClient.readContract({
            address: vaultAddress,
            abi: MORPHO_VAULT_ABI,
            functionName: "convertToAssets",
            args: [shares]
          });
        }
        const decimals = vaultConfig.asset.decimals;
        return {
          vaultAddress,
          vaultSymbol: vaultConfig.symbol,
          shares,
          sharesFormatted: formatUnits(shares, decimals),
          assetsValue,
          assetsValueFormatted: formatUnits(assetsValue, decimals),
          maxWithdraw,
          maxWithdrawFormatted: formatUnits(maxWithdraw, decimals),
          maxRedeem,
          maxRedeemFormatted: formatUnits(maxRedeem, decimals),
          walletBalance,
          walletBalanceFormatted: formatUnits(walletBalance, decimals),
          assetDecimals: decimals,
          assetSymbol: vaultConfig.asset.symbol
        };
      } catch (error) {
        console.error(`Failed to fetch user vault position for ${vaultAddress}:`, error);
        return null;
      }
    },
    enabled: !!publicClient && !!vaultAddress && !!userAddress,
    refetchInterval: 15e3,
    staleTime: 1e4
  });
}
export function useMorphoUserAllVaultPositions(userAddress, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-user-all-vault-positions", userAddress, chainId],
    queryFn: async () => {
      if (!publicClient || !userAddress) return [];
      const vaultConfigs = Object.values(MORPHO_VAULTS).filter((v) => v.chainId === chainId);
      const positions = await Promise.all(
        vaultConfigs.map(async (vaultConfig) => {
          try {
            const [shares, maxWithdraw, maxRedeem, walletBalance] = await publicClient.multicall({
              allowFailure: false,
              contracts: [
                {
                  address: vaultConfig.address,
                  abi: MORPHO_VAULT_ABI,
                  functionName: "balanceOf",
                  args: [userAddress]
                },
                {
                  address: vaultConfig.address,
                  abi: MORPHO_VAULT_ABI,
                  functionName: "maxWithdraw",
                  args: [userAddress]
                },
                {
                  address: vaultConfig.address,
                  abi: MORPHO_VAULT_ABI,
                  functionName: "maxRedeem",
                  args: [userAddress]
                },
                {
                  address: vaultConfig.asset.address,
                  abi: ERC20_ABI,
                  functionName: "balanceOf",
                  args: [userAddress]
                }
              ]
            });
            let assetsValue = 0n;
            if (shares > 0n) {
              assetsValue = await publicClient.readContract({
                address: vaultConfig.address,
                abi: MORPHO_VAULT_ABI,
                functionName: "convertToAssets",
                args: [shares]
              });
            }
            const decimals = vaultConfig.asset.decimals;
            return {
              vaultAddress: vaultConfig.address,
              vaultSymbol: vaultConfig.symbol,
              shares,
              sharesFormatted: formatUnits(shares, decimals),
              assetsValue,
              assetsValueFormatted: formatUnits(assetsValue, decimals),
              maxWithdraw,
              maxWithdrawFormatted: formatUnits(maxWithdraw, decimals),
              maxRedeem,
              maxRedeemFormatted: formatUnits(maxRedeem, decimals),
              walletBalance,
              walletBalanceFormatted: formatUnits(walletBalance, decimals),
              assetDecimals: decimals,
              assetSymbol: vaultConfig.asset.symbol
            };
          } catch (error) {
            console.error(`Failed to fetch user position for vault ${vaultConfig.symbol}:`, error);
            return null;
          }
        })
      );
      return positions.filter((p) => p !== null);
    },
    enabled: !!publicClient && !!userAddress,
    refetchInterval: 15e3,
    staleTime: 1e4
  });
}
export function useMorphoVaultPreview(vaultAddress, amount, type, chainId = UniverseChainId.Mainnet) {
  const publicClient = usePublicClient({ chainId });
  return useQuery({
    queryKey: ["morpho-vault-preview", vaultAddress, amount.toString(), type, chainId],
    queryFn: async () => {
      if (!publicClient || !vaultAddress || amount === 0n) return 0n;
      try {
        if (type === "deposit") {
          return await publicClient.readContract({
            address: vaultAddress,
            abi: MORPHO_VAULT_ABI,
            functionName: "previewDeposit",
            args: [amount]
          });
        } else {
          return await publicClient.readContract({
            address: vaultAddress,
            abi: MORPHO_VAULT_ABI,
            functionName: "previewRedeem",
            args: [amount]
          });
        }
      } catch (error) {
        console.error(`Failed to preview ${type} for vault ${vaultAddress}:`, error);
        return 0n;
      }
    },
    enabled: !!publicClient && !!vaultAddress && amount > 0n,
    refetchInterval: 1e4,
    staleTime: 5e3
  });
}
