"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import {
  fetchMetaMorphoVaults,
  fetchMetaMorphoVaultById,
  fetchUserVaultPositions,
  fetchUserVaultTransactions,
  fetchVaultTransactions,
  fetchFinancialsDailySnapshots,
  fetchVaultDailySnapshots,
  fetchPositionSnapshots,
  formatTokenAmount
} from "uniswap/src/features/morpho/api/morphoSubgraph";
import { MORPHO_VAULTS } from "constants/morpho";
const STALE_TIME = 3e4;
const REFETCH_INTERVAL = 6e4;
const HISTORICAL_STALE_TIME = 3e5;
function getWhitelistedVaultAddresses(chainId) {
  return Object.values(MORPHO_VAULTS).filter((v) => v.chainId === chainId).map((v) => v.address.toLowerCase());
}
export function useMetaMorphoVaultsSubgraph(chainId = UniverseChainId.Mainnet) {
  const whitelistedAddresses = getWhitelistedVaultAddresses(chainId);
  return useQuery({
    queryKey: ["metamorpho-vaults-subgraph", chainId, whitelistedAddresses],
    queryFn: async () => {
      const allVaults = await fetchMetaMorphoVaults(chainId);
      const vaults = allVaults.filter((v) => whitelistedAddresses.includes(v.id.toLowerCase()));
      return vaults.map((vault) => {
        const rate = parseFloat(vault.rate || "0");
        const apy = rate * 100;
        const feePercent = parseFloat(vault.fee || "0") * 100;
        const assetDecimals = vault.asset?.decimals ?? 18;
        const totalAssetsFormatted = formatTokenAmount(vault.totalAssets || "0", assetDecimals);
        const totalAssets = parseFloat(vault.totalAssets || "0");
        const totalShares = parseFloat(vault.totalShares || "1");
        const sharePrice = totalShares > 0 ? totalAssets / totalShares : 1;
        return {
          ...vault,
          apy,
          feePercent,
          totalAssetsFormatted,
          sharePrice
        };
      });
    },
    staleTime: STALE_TIME,
    refetchInterval: REFETCH_INTERVAL
  });
}
export function useMetaMorphoVaultById(vaultId, chainId = UniverseChainId.Mainnet) {
  const whitelistedAddresses = getWhitelistedVaultAddresses(chainId);
  return useQuery({
    queryKey: ["metamorpho-vault-by-id", vaultId, chainId],
    queryFn: async () => {
      if (!vaultId) return null;
      if (!whitelistedAddresses.includes(vaultId.toLowerCase())) return null;
      const vault = await fetchMetaMorphoVaultById(vaultId, chainId);
      if (!vault) return null;
      const rate = parseFloat(vault.rate || "0");
      const apy = rate * 100;
      const feePercent = parseFloat(vault.fee || "0") * 100;
      const assetDecimals = vault.asset?.decimals ?? 18;
      const totalAssetsFormatted = formatTokenAmount(vault.totalAssets || "0", assetDecimals);
      const totalAssets = parseFloat(vault.totalAssets || "0");
      const totalShares = parseFloat(vault.totalShares || "1");
      const sharePrice = totalShares > 0 ? totalAssets / totalShares : 1;
      return {
        ...vault,
        apy,
        feePercent,
        totalAssetsFormatted,
        sharePrice
      };
    },
    enabled: !!vaultId,
    staleTime: STALE_TIME,
    refetchInterval: REFETCH_INTERVAL
  });
}
export function useUserVaultPositionsSubgraph(userAddress, chainId = UniverseChainId.Mainnet) {
  const whitelistedAddresses = getWhitelistedVaultAddresses(chainId);
  return useQuery({
    queryKey: ["metamorpho-user-vault-positions", userAddress, chainId, whitelistedAddresses],
    queryFn: async () => {
      if (!userAddress) return [];
      const positions = await fetchUserVaultPositions(userAddress, chainId);
      return positions.filter((p) => whitelistedAddresses.includes(p.vault?.id?.toLowerCase() ?? ""));
    },
    enabled: !!userAddress,
    staleTime: STALE_TIME,
    refetchInterval: REFETCH_INTERVAL
  });
}
function generateUserColor(address) {
  const hash = address.slice(2, 8);
  const hue = parseInt(hash, 16) % 360;
  return `hsl(${hue}, 70%, 50%)`;
}
function formatVaultTransactions(transactions) {
  return transactions.map((tx) => {
    const decimals = tx.token?.decimals ?? 18;
    const amount = parseFloat(tx.assets) / Math.pow(10, decimals);
    const tokenSymbol = tx.token?.symbol ?? "UNKNOWN";
    const typeMap = {
      DEPOSIT: "Deposit",
      WITHDRAW: "Withdraw"
    };
    return {
      id: tx.id,
      hash: tx.hash,
      date: new Date(Number(tx.timestamp) * 1e3).toLocaleString(),
      type: typeMap[tx.type] ?? "Deposit",
      amount: `${amount.toLocaleString(void 0, { maximumFractionDigits: 4 })} ${tokenSymbol}`,
      amountUsd: "--",
      tokenSymbol,
      userAddress: `${tx.sender.slice(0, 6)}...${tx.sender.slice(-4)}`,
      userColor: generateUserColor(tx.sender),
      txHash: `${tx.hash.slice(0, 6)}...${tx.hash.slice(-4)}`,
      timestamp: Number(tx.timestamp),
      vaultId: tx.vaultId,
      vaultName: tx.vaultName
    };
  });
}
export function useUserVaultTransactions(userAddress, chainId = UniverseChainId.Mainnet, limit = 50) {
  const whitelistedAddresses = getWhitelistedVaultAddresses(chainId);
  return useQuery({
    queryKey: ["metamorpho-user-vault-transactions", userAddress, chainId, limit, whitelistedAddresses],
    queryFn: async () => {
      if (!userAddress) return [];
      const transactions = await fetchUserVaultTransactions(userAddress, chainId, limit);
      const filtered = transactions.filter((tx) => whitelistedAddresses.includes(tx.vaultId?.toLowerCase() ?? ""));
      return formatVaultTransactions(filtered);
    },
    enabled: !!userAddress,
    staleTime: STALE_TIME,
    refetchInterval: REFETCH_INTERVAL
  });
}
export function useVaultTransactions(vaultId, chainId = UniverseChainId.Mainnet, limit = 50) {
  const whitelistedAddresses = getWhitelistedVaultAddresses(chainId);
  return useQuery({
    queryKey: ["metamorpho-vault-transactions", vaultId, chainId, limit],
    queryFn: async () => {
      if (!vaultId) return [];
      if (!whitelistedAddresses.includes(vaultId.toLowerCase())) return [];
      const transactions = await fetchVaultTransactions(vaultId, chainId, limit);
      return formatVaultTransactions(transactions);
    },
    enabled: !!vaultId && whitelistedAddresses.includes(vaultId.toLowerCase()),
    staleTime: STALE_TIME,
    refetchInterval: REFETCH_INTERVAL
  });
}
export function useVaultHistory(vaultId, chainId = UniverseChainId.Mainnet, days = 30) {
  const whitelistedAddresses = getWhitelistedVaultAddresses(chainId);
  return useQuery({
    queryKey: ["metamorpho-vault-history", vaultId, chainId, days],
    queryFn: async () => {
      if (!vaultId) return [];
      if (!whitelistedAddresses.includes(vaultId.toLowerCase())) return [];
      const startTimestamp = Math.floor(Date.now() / 1e3) - days * 24 * 60 * 60;
      const snapshots = await fetchVaultDailySnapshots(vaultId, chainId, startTimestamp);
      return snapshots.map((snapshot) => {
        const totalAssets = parseFloat(snapshot.totalAssets || "0");
        const totalShares = parseFloat(snapshot.totalShares || "1");
        const sharePrice = totalShares > 0 ? totalAssets / totalShares : 1;
        const rate = parseFloat(snapshot.rate || "0");
        const apy = rate * 100;
        return {
          date: new Date(Number(snapshot.timestamp) * 1e3).toLocaleDateString(),
          timestamp: Number(snapshot.timestamp),
          totalAssets,
          totalAssetsUSD: parseFloat(snapshot.totalAssetsUSD || "0"),
          sharePrice,
          apy
        };
      });
    },
    enabled: !!vaultId && whitelistedAddresses.includes(vaultId.toLowerCase()),
    staleTime: HISTORICAL_STALE_TIME
  });
}
export function useProtocolFinancialsHistory(chainId = UniverseChainId.Mainnet, days = 30) {
  return useQuery({
    queryKey: ["protocol-financials-history", chainId, days],
    queryFn: async () => {
      const startTimestamp = Math.floor(Date.now() / 1e3) - days * 24 * 60 * 60;
      const snapshots = await fetchFinancialsDailySnapshots(chainId, startTimestamp);
      return snapshots.map((snapshot) => {
        const totalDepositUSD = parseFloat(snapshot.totalDepositBalanceUSD || "0");
        const totalBorrowUSD = parseFloat(snapshot.totalBorrowBalanceUSD || "0");
        const utilization = totalDepositUSD > 0 ? totalBorrowUSD / totalDepositUSD * 100 : 0;
        return {
          date: new Date(Number(snapshot.timestamp) * 1e3).toLocaleDateString(),
          timestamp: Number(snapshot.timestamp),
          totalValueLockedUSD: parseFloat(snapshot.totalValueLockedUSD || "0"),
          totalDepositUSD,
          totalBorrowUSD,
          dailyDepositUSD: parseFloat(snapshot.dailyDepositUSD || "0"),
          dailyBorrowUSD: parseFloat(snapshot.dailyBorrowUSD || "0"),
          utilization
        };
      });
    },
    staleTime: HISTORICAL_STALE_TIME
  });
}
export function useUserPositionHistory(positionId, chainId = UniverseChainId.Mainnet, days = 30) {
  return useQuery({
    queryKey: ["user-position-history", positionId, chainId, days],
    queryFn: async () => {
      if (!positionId) return [];
      const startTimestamp = Math.floor(Date.now() / 1e3) - days * 24 * 60 * 60;
      const snapshots = await fetchPositionSnapshots(positionId, chainId, startTimestamp);
      return snapshots.map((snapshot) => ({
        date: new Date(Number(snapshot.timestamp) * 1e3).toLocaleDateString(),
        timestamp: Number(snapshot.timestamp),
        shares: parseFloat(snapshot.shares || "0"),
        balanceUSD: parseFloat(snapshot.balanceUSD || "0")
      }));
    },
    enabled: !!positionId,
    staleTime: HISTORICAL_STALE_TIME
  });
}
